 use derrick_cli::upgrade::ReqwestReleaseClient;

 type TestResult<T = ()> = Result<T, Box<dyn std::error::Error>>;

 #[tokio::test(flavor = "multi_thread")]
 async fn integration_latest_release_has_semver_tag_and_assets_when_network_enabled() -> TestResult {
     let network_enabled = std::env::var("DERRICK_TEST_NETWORK").is_ok();
     if !network_enabled {
         return Ok(());
     }

     let release = ReqwestReleaseClient::new().latest_release().await?;
     let tag_name = release.tag_name();
     assert!(!tag_name.trim().is_empty(), "release tag name was empty");

     semver::Version::parse(tag_name)?;

     assert!(
         !release.assets().is_empty(),
         "latest release had no downloadable assets"
     );
     for asset in release.assets() {
         assert!(
             !asset.name().trim().is_empty(),
             "latest release asset name was empty"
         );
     }
     Ok(())
 }

